  "items:ring_master_attack:description": "Conquistado por uma lâmina que encontrou cada brecha em cada guarda. Concede 2% de penetração de armadura.",
  "items:ring_master_attack:name": "Anel do Mestre das Lâminas",
  "items:ring_master_completion:description": "Usado apenas por aqueles que dominaram as vinte e três disciplinas. Um aro silencioso de ouro, concedido, jamais comprado.",
  "items:ring_master_hunting:name": "Anel do Armadilheiro",
  "items:ring_master_hunting:description": "Alisado por mil armadilhas montadas e disparadas. Cada espólio de uma captura tem 5% de chance de cair em dobro.",
  "items:ring_master_completion:name": "Anel da Completude",
  "items:ring_master_cooking:description": "Manchado por cada prato que já supervisionou. Refeições preparadas enquanto usado nunca falham.",
  "items:ring_master_cooking:name": "Anel do Cozinheiro de Almas",
  "items:ring_master_defence:description": "Desviou golpes que teriam derrubado guardas menores. Concede 2% de chance de bloqueio.",
  "items:ring_master_defence:name": "Anel do Bastião",
  "items:ring_master_farming:description": "Cheira a terra revolvida e estações pacientes. As plantações amadurecem 8% mais rápido enquanto usado.",
  "items:ring_master_farming:name": "Anel do Guardião das Covas",
  "items:ring_master_fishing:description": "Cheira levemente a águas profundas e coisas mais antigas. 5% de chance de conseguir uma pescaria dupla.",
  "items:ring_master_fishing:name": "Anel do Pescador do Vazio",
  "items:ring_master_foraging:description": "Cravejado com uma lasca de cada folha que já roçou. 5% de chance de colher uma colheita dupla.",
  "items:ring_master_foraging:name": "Anel do Coletor Selvagem",
  "items:ring_master_herblore:description": "Embebido em vapores amargos por mais tempo do que a memória alcança. Tônicos e poções duram 10% mais enquanto usado.",
  "items:ring_master_herblore:name": "Anel do Mestre dos Venenos",
  "items:ring_master_jewelcrafting:description": "Captura a luz como mil gemas sem lapidar. 5% de chance de lapidar uma gema dupla.",
  "items:ring_master_jewelcrafting:name": "Anel do Mestre das Gemas",
  "items:ring_master_leatherworking:description": "Entalhado por um mestre que não desperdiçava nada. 5% de chance de o ofício poupar seus materiais.",
  "items:ring_master_leatherworking:name": "Anel do Mestre Curtidor",
  "items:ring_master_magic:description": "Forjado com o resíduo de mil escudos arcanos estilhaçados. Concede 3% de ruptura de escudo.",
  "items:ring_master_magic:name": "Anel do Arquimago",
  "items:ring_master_mining:description": "Forjado nos veios mais profundos, lembra-se de cada veio que já tocou. 5% de chance de extrair minério duplo.",
  "items:ring_master_mining:name": "Anel do Rompedor das Profundezas",
  "items:ring_master_power:description": "Carrega o peso de cada golpe final de um senhor da guerra. Concede 3% de dano crítico.",
  "items:ring_master_power:name": "Anel do Senhor da Guerra",
  "items:ring_master_ranged:description": "Aguça a vista até que nenhuma esquiva pareça rápida o suficiente. Concede 2% de precisão.",
  "items:ring_master_ranged:name": "Anel do Olho de Falcão",
  "items:ring_master_runecrafting:description": "Vibra suavemente com escrita arcana vinculada. 5% de chance de vincular uma runa dupla.",
  "items:ring_master_runecrafting:name": "Anel do Vinculador de Runas",
  "items:ring_master_slayer:description": "Marcado com a contagem de mil contratos. Rende 10% mais pontos de Caçador.",
  "items:ring_master_slayer:name": "Anel do Mestre de Recompensas",
  "items:ring_master_smithing:description": "Chamuscado por mil forjas, nunca derretido. 5% de chance de a forja poupar seus materiais.",
