  "items:skytalon_recurve:name": "Arco Recurvo de Garra Celeste",
  "items:slag_carapace:description": "Quitina endurecida e fundida em lava, de uma abominação de escória. Material de qualidade para peças de armadura da torre.",
  "items:slag_carapace:name": "Carapaça de Escória",
  "items:slagcarapace_plate:name": "Placa de Carapaça de Escória",
  "items:slagforged_sword:name": "Espada de Forjado em Escória",
  "items:slagheart_cuirass:name": "Couraça de Coração de Escória",
  "items:slagweave_cape:name": "Capa de Escória",
  "items:slayer_amulet:description": "Um amuleto cristalino cravejado com um fragmento de arauto do vazio. Emana um poder frio e preciso em todos os estilos de combate.",
  "items:slayer_amulet:name": "Amuleto do Caçador",
  "items:slayer_combat_draught:description": "Destilada da essência da Torre do Caçador. Acelera seus golpes (-450ms de intervalo de ataque) e aguça sua mira (+8% de crítico) por 10 minutos.",
  "items:slayer_combat_draught:name": "Beberagem de Combate do Caçador",
  "items:slayer_greaves:description": "Grevas reforçadas com os fragmentos partidos de dentes de presa-do-pavor. Feitas para presas acima da sua posição: +20% de dano contra monstros com nível de combate superior ao seu.",
  "items:slayer_greaves:name": "Grevas do Caçador",
  "items:slayer_helm:description": "Um elmo magistral forjado da essência dos piores horrores da Torre do Caçador. Marca o encargo de seu portador: +20% de dano contra o alvo atual da tarefa, e nenhum item de guarda é necessário contra qualquer ameaça da torre enquanto estiver equipado.",
  "items:slayer_helm:name": "Elmo do Caçador",
  "items:slayer_hunters_cape:description": "Uma capa desgastada que Brenna entrega a caçadores que conquistaram seus primeiros trinta contratos. O primeiro golpe de cada caçada acerta com mais força: +15% de dano contra um alvo ileso.",
  "items:slayer_hunters_cape:name": "Capa do Caçador",
  "items:slayer_hunters_elixir:description": "Reservado a Caçadores veteranos. Apressa seus ataques (-600ms de intervalo), +12% de crítico, +20% de dano crítico por 30 minutos. Uptime sustentado superior à Beberagem de Combate.",
  "items:slayer_hunters_elixir:name": "Elixir de Caça do Caçador",
  "items:slayer_vambraces:description": "Braçadeiras confeccionadas com pele chamuscada de Desgraçado de Brasa e couro endurecido da torre. Cada abate na caçada cicatriza as feridas do caçador: +4 de vida por abate.",
  "items:slayer_vambraces:name": "Braçadeiras do Caçador",
  "items:slayer_war_brew:description": "A fórmula de um antigo Mestre Caçador. Apressa muito seus ataques (-750ms de intervalo), +20% de crítico, +30% de dano crítico por 60 minutos. Reservada às maiores caçadas.",
  "items:slayer_war_brew:name": "Beberagem de Guerra do Caçador",
  "items:slayer_ward_capsule:description": "Um recipiente selado contendo os quatro componentes de guarda da torre, fundidos em um único núcleo protetor.",
  "items:slayer_ward_capsule:name": "Cápsula de Guarda do Caçador",
  "items:smokeweave_cape:name": "Capa de Fumaça",
  "items:smugglers_key:name": "Chave do Contrabandista",
  "items:sootscale_greaves:name": "Grevas de Escama Fuliginosa",
  "items:sorrow_staff:name": "Cajado de Tristeza",
  "items:soul_amulet:name": "Amuleto de Alma",
  "items:soul_flayer_fang:description": "Uma presa curva com fedor de almas queimadas. Drop raro do esfolador de almas, cobiçada como troféu para o Mural de Troféus do acampamento.",
  "items:cinderwretch_hide:name": "Pele do Desgraçado de Brasa",
  "items:cinderwretch_hide:description": "Uma pele resistente, enegrecida por um coração de brasas eterno, arrancada de um Desgraçado de Brasa nas profundezas da torre. Componente de fabricação para as Braçadeiras do Caçador.",
  "items:soul_flayer_fang:name": "Presa do Esfolador de Almas",
  "items:soul_veil:description": "Uma mortalha reluzente tecida de essência de aether e runas do vazio. Protege contra ataques de criaturas incorpóreas.",
  "items:soul_veil:name": "Véu de Alma",
