  "quests:q_blackthorn_1:description": "Abata 20 Rootlings que se soltam da vegetação rasteira na Mata do Espinho-Negro; a mata aprendeu a se defender.",
  "quests:q_blackthorn_1:name": "Rumo à Mata do Espinho-Negro",
  "quests:q_blackthorn_2:description": "Avance mais fundo na Mata do Espinho-Negro, rumo aos túmulos sob suas raízes, e derrote 25 Rootlings Retorcidos.",
  "quests:q_blackthorn_2:name": "A Profundeza Retorcida",
  "quests:q_boar_hunter:description": "Mate 15 Javalis Selvagens nos Pastos. Sem cerca nem pastor, adotaram hábitos próprios, e o Bastião das Brasas precisa de seus couros.",
  "quests:q_boar_hunter:name": "A Caçada Selvagem",
  "quests:q_crypt_1:description": "Entre na Cripta e mate 10 Esqueletos Guerreiros. A Ordem dos Guardiões dos Túmulos os selou outrora; o selo já não resiste em todo lugar.",
  "quests:q_crypt_1:name": "Ossos dos Tombados",
  "quests:q_crypt_2:description": "Os salões inferiores da Cripta são guardados por Esqueletos Lanceiros, uma guarnição que já não cobra soldo. Derrube 20 deles.",
  "quests:q_crypt_2:name": "Mortos Inflexíveis",
  "quests:q_crypt_3:description": "Esqueletos Magos de Gelo assombram as câmaras mais profundas da Cripta. Destrua 10 deles antes que o congelem por inteiro.",
  "quests:q_crypt_3:name": "Silêncio Gélido",
  "quests:q_dire_wolf_hunt:description": "Lobos Ferozes espreitam nas profundezas da Floresta Selvagem, maiores do que um lobo deveria ser. Mate 15 desses predadores ferozes.",
  "quests:q_dire_wolf_hunt:name": "Terror das Terras Selvagens",
  "quests:q_fighter_1:description": "Derrote 75 inimigos no total. Sangue e suor forjam o lutador de que o Bastião das Brasas precisa.",
  "quests:q_fighter_1:name": "Lutador Experiente",
  "quests:q_fighter_2:description": "Derrube 200 inimigos no total. Os Servos já começam a lembrar seu nome.",
  "quests:q_fighter_2:name": "Guerreiro Endurecido",
  "quests:q_fighter_3:description": "Derrote 500 inimigos no total. Cada inimigo tombado é um registro que as cinzas jamais recebem.",
  "quests:q_fighter_3:name": "Veterano de Cem Batalhas",
  "quests:q_first_blood:description": "Mate 10 Goblins nas Terras da Fronteira; já saquearam as últimas fazendas perto do Bastião das Brasas por tempo demais.",
  "quests:q_first_blood:name": "Sangue Goblin",
  "quests:q_first_steps:description": "Cace 5 galinhas nos Pastos, às portas do Bastião das Brasas: um primeiro manejo de uma arma, nada mais.",
  "quests:q_first_steps:name": "Primeiros Passos",
  "quests:q_frost_hound:description": "Cães de Gelo rondam as Cavernas de Gelo, onde o poço cavou fundo demais e encontrou o frio do vazio. Cace 15 deles.",
  "quests:q_frost_hound:name": "A Caçada Gélida",
  "quests:q_gatherer:description": "Colete 50 itens de qualquer tipo para o Bastião das Brasas: corte lenha, minere minério, colha ervas ou saqueie monstros.",
  "quests:q_gatherer:name": "Coletor",
  "quests:q_gatherer_2:description": "Colete 5.000 itens no total para o Bastião das Brasas. Esta terra só entrega o pouco que lhe resta a quem persiste.",
  "quests:q_gatherer_2:name": "Colecionador Incansável",
  "quests:q_goblin_slayer:description": "Repila ainda mais a horda goblin: mate 30 Goblins nas Terras da Fronteira, outrora a muralha-escudo do Confim.",
  "quests:q_goblin_slayer:name": "Algoz de Goblins",
  "quests:q_miner_1:description": "Alcance o nível 5 de Mineração e abra veios melhores para a forja do Bastião das Brasas.",
  "quests:q_miner_1:name": "Picareta e Pedra",
  "quests:q_miner_2:description": "Alcance o nível 30 de Mineração. Os veios mais profundos das Terras da Fronteira exigem um braço mais forte.",
  "quests:q_miner_2:name": "Vontade de Ferro",
  "quests:q_miner_3:description": "Alcance o nível 50 de Mineração. Os minérios mais raros do Confim jazem bem abaixo da superfície, mais fundo que nunca.",
  "quests:q_miner_3:name": "O Chamado das Profundezas",
  "quests:q_moss_golem_hunt:description": "Golens de Musgo invadiram as clareiras da floresta; até a mata precisa de guardas agora. Despedace 15 deles.",
  "quests:q_moss_golem_hunt:name": "Ameaça Musgosa",
  "quests:q_roc_fledgling:description": "Filhotes de Roc dominam as correntes térmicas das Terras Altas, onde o céu ainda corre limpo. Abata 10 dessas aves colossais.",
  "quests:q_roc_fledgling:name": "Vigília Celeste das Terras Altas",
  "quests:q_shaman_hunt:description": "Os Goblins Xamãs sugam Essência Tênue das velhas fogueiras de guarda e agitam a horda para a guerra. Silencie 10 deles.",
  "quests:q_shaman_hunt:name": "Caça ao Xamã",
  "quests:q_skiller_1:description": "Alcance um nível total combinado de 20 em todas as perícias; o Bastião das Brasas conta em dobro cada mão capaz.",
  "quests:q_skiller_1:name": "Faz-Tudo",
  "quests:q_skiller_2:description": "Alcance um nível total combinado de 50. Quem só domina um ofício não dura muito neste mundo.",
  "quests:q_skiller_2:name": "Aventureiro Versátil",
  "quests:q_skiller_3:description": "Alcance um nível total combinado de 75. Muitos caminhos o trouxeram até aqui, e o Bastião das Brasas não esquece nenhum deles.",
  "quests:q_skiller_3:name": "Aventureiro Experiente",
  "quests:q_skiller_4:description": "Alcance um nível total combinado de 100. Poucos dos que partiram do Bastião das Brasas chegaram tão longe.",
  "quests:q_skiller_4:name": "Senda da Maestria",
  "quests:q_skiller_5:description": "Alcance um nível total combinado de 150. Seus feitos agora são contados junto ao fogo do Bastião das Brasas, como outrora a lenda de Hearthforge, onde todos os ofícios do Confim hibernaram a queda do mundo.",
  "quests:q_skiller_5:name": "Lenda de Hearthforge",
  "quests:q_slagpit_1:description": "Adentre o Poço de Escória, onde outrora se fundia o ferro divino, e extermine 20 Aranhas do Fosso à espreita nas sombras.",
  "quests:q_slagpit_1:name": "Rumo ao Poço",
  "quests:q_slagpit_2:description": "Revenantes de Ferro patrulham as passagens mais profundas, ferreiros que morreram em sua armadura e nunca foram dispensados. Derrube 10 desses constructos imortais.",
  "quests:q_slagpit_2:name": "Assombração de Ferro",
  "quests:q_smith_journeyman:description": "Alcance o nível 20 de Ferraria. A forja do Bastião das Brasas recompensa a paciência: domine o básico antes de encarar metais mais difíceis.",
  "quests:q_smith_journeyman:name": "Ferreiro Oficial",
  "quests:q_smith_master:description": "Alcance o nível 50 de Ferraria. Só os verdadeiramente dedicados conseguem trabalhar os metais mais raros do Confim: o ferro divino não perdoa a impaciência.",
  "quests:q_smith_master:name": "Mestre da Forja",
  "quests:q_stag_hunter:description": "Cervos Selvagens, como monumentos, dominam os Coutos de Caça da Floresta Selvagem. Abata 20 dessas feras altivas.",
  "quests:q_stag_hunter:name": "Rei da Mata",
  "quests:q_thorn_wolf_pack:description": "Os Lobos Espinhosos da Mata do Espinho-Negro são mais perigosos que seus semelhantes; a mata os afiou. Mate 20 deles.",
  "quests:q_thorn_wolf_pack:name": "Matilha de Lobos Espinhosos",
  "quests:q_wolf_slayer:description": "Cace 15 Lobos Cinzentos nos Coutos de Caça da Floresta Selvagem; tudo ali cresceu mais, desde que ninguém mais caça.",
  "quests:q_wolf_slayer:name": "Rumo à Floresta Selvagem",
  "quests:q_woodcutter_1:description": "Alcance o nível 5 de Corte de Lenha. Um machado afiado e um coração firme bastam; o Bastião das Brasas não pede mais que isso.",
  "quests:q_woodcutter_1:name": "Rumo à Mata",
  "quests:q_woodcutter_2:description": "Alcance o nível 15 de Corte de Lenha para cortar árvores de Carvalho; o acampamento precisa de mais que lenha fina.",
  "quests:q_woodcutter_2:name": "Lenhador Experiente",
  "quests:q_woodcutter_3:description": "Alcance o nível 30 de Corte de Lenha. Bosques ancestrais revelam seus segredos apenas aos dignos; o Espinho-Negro prefere reverência à pressa.",
  "quests:q_woodcutter_3:name": "Mestre do Machado",
