  // ── New Haven / Encampment (0.3.0, Task #358): 15 Gebäude-Namen + Flavor ──
  "campBuildings:camp_townhall:name": "Casa do Conselho",
  "campBuildings:camp_townhall:description": "Primeiro um casebre com uma mesa, depois uma casa com sino: quem o ouve sabe que em New Haven alguém está decidindo.",
  "campBuildings:camp_watchtower:name": "Torre de Vigia",
  "campBuildings:camp_watchtower:description": "Enquanto alguém vigia lá em cima, o trabalho embaixo não descansa.",
  "campBuildings:camp_storehouse:name": "O Armazém",
  "campBuildings:camp_storehouse:description": "Erguido sobre estacas de pedra, para que nem a umidade nem os ratos entrem. Voss mandou a planta, junto com a ordem de contar tudo duas vezes.",
  "campBuildings:camp_scrivener_tent:name": "A Tenda do Escrivão",
  "campBuildings:camp_scrivener_tent:description": "O que se escreve à noite não precisa ser decidido de manhã.",
  "campBuildings:camp_fishing_hut:name": "Cabana do Pescador",
  "campBuildings:camp_fishing_hut:description": "O vau rende mais que passagem, para quem sabe ficar quieto o bastante.",
  "campBuildings:camp_sawpit:name": "A Fossa de Serrar",
  "campBuildings:camp_sawpit:description": "Um homem em cima, outro embaixo na serragem; de um jeito ou de outro, saem vigas.",
  "campBuildings:camp_mine_adit:name": "A Boca da Mina",
  "campBuildings:camp_mine_adit:description": "A encosta não dá nada de graça, mas dá.",
  "campBuildings:camp_seed_garden:name": "O Jardim de Sementes",
  "campBuildings:camp_seed_garden:description": "Esta terra há muito não dá nada de bom; estão lhe ensinando a confiar de novo.",
  "campBuildings:camp_fence_tent:name": "A Tenda do Receptador",
  "campBuildings:camp_fence_tent:description": "Ninguém pergunta de onde vem a mercadoria. É exatamente esse o negócio.",
  "campBuildings:camp_workyard:name": "O Pátio de Ofícios",
  "campBuildings:camp_workyard:description": "Bancada após bancada sob uma mesma lona: todo ofício rende mais quando o vizinho segura a tenaz.",
  "campBuildings:camp_smelter:name": "O Forno de Fundição",
  "campBuildings:camp_smelter:description": "O fogo não tem expediente: o que entra volta em barras, com ou sem alguém olhando.",
  "campBuildings:camp_smokehouse:name": "O Defumadouro",
  "campBuildings:camp_smokehouse:description": "A fumaça é o cozinheiro mais paciente do reino.",
  "campBuildings:camp_trophy_wall:name": "O Mural de Troféus",
  "campBuildings:camp_trophy_wall:description": "Brenna paga por cabeças; o mural lembra que foram entregues.",
  "campBuildings:camp_warden_shrine:name": "Santuário dos Silenciosos",
  "campBuildings:camp_warden_shrine:description": "Sem imagem, sem boca, sem mão: só uma pedra erguida e a chance de alguém estar ouvindo.",
  "campBuildings:camp_trade_post:name": "O Posto de Trocas",
  "campBuildings:camp_trade_post:description": "Mux manda a carroça sempre que a estrada permite; os preços são justos, diz Mux.",

