  "items:fiber_nettle:name": "Fibra de Urtiga",
  "items:fiber_nettle:description": "Talos de urtiga descascados e secos até que a ardência desapareça e reste apenas o fio.",
  "items:fiber_flax:name": "Linho",
  "items:fiber_flax:description": "Talos esguios maceirados e penteados até ficarem lisos, o fio mais antigo já fiado no Reach.",
  "items:fiber_thornhemp:name": "Cânhamo Espinhoso",
  "items:fiber_thornhemp:description": "Fibra grosseira de uma cerca viva que reage, resistente o bastante para desviar o fio de uma lâmina.",
  "items:fiber_ghostsilk:name": "Seda Fantasma",
  "items:fiber_ghostsilk:description": "Filamentos pálidos fiados por algo que vive onde a luz se esgota.",
  "items:fiber_starflax:name": "Linho Estelar",
  "items:fiber_starflax:description": "Fibra com um leve brilho frio, como se lembrasse o céu sob o qual cresceu.",
  "items:nettle_seed:name": "Semente de Urtiga",
  "items:nettle_seed:description": "Semente negra e minúscula, plante-a e proteja as mãos na hora da colheita.",
  "items:flax_seed:name": "Semente de Linho",
  "items:flax_seed:description": "Semente pequena e oleosa da qual cresce o tecido mais antigo do Reach.",
  "items:thornhemp_seed:name": "Semente de Cânhamo Espinhoso",
  "items:thornhemp_seed:description": "Semente de casca dura de uma cerca viva que prefere morder a florescer.",
  "items:ghostsilk_seed:name": "Semente de Seda Fantasma",
  "items:ghostsilk_seed:description": "Semente pálida como osso, dizem que brota melhor onde mais nada quer crescer.",
  "items:starflax_seed:name": "Semente de Linho Estelar",
  "items:starflax_seed:description": "Semente que brilha fracamente ao anoitecer, paciente o bastante para esperar uma estação inteira sob a terra.",
  "items:cloth_nettle:name": "Pano de Urtiga",
  "items:cloth_nettle:description": "Tecido de trama grosseira feito da fibra mais humilde do Reach, quente o bastante para uma primeira túnica.",
  "items:cloth_linen:name": "Tecido de Linho",
  "items:cloth_linen:description": "Linho macio e de trama uniforme, o tecido de trabalho de qualquer bancada de alfaiate.",
  "items:cloth_thornlinen:name": "Tecido Espinhoso",
  "items:cloth_thornlinen:description": "Linho tecido cerrado com fio de cânhamo espinhoso, rígido o bastante para desviar um golpe leve.",
  "items:cloth_ghostweave:name": "Tecido Fantasma",
  "items:cloth_ghostweave:description": "Tecido feito de seda fantasma, pálido e fresco, dizem que abafa até o próprio batimento cardíaco do conjurador.",
  "items:cloth_starweave:name": "Tecido Estelar",
  "items:cloth_starweave:description": "Linho estelar tecido em um pano que guarda um leve brilho frio muito depois de o tear parar.",
  "items:bait_worm:name": "Isca de Minhoca",
  "items:bait_maggot:name": "Isca de larvas",
  "items:bait_maggot:description": "Larvas gordas tiradas da lama onde os peixes se juntam; a caça das terras de cinza e espinhos não resiste a elas.",
  "items:bait_crab:name": "Isca de caranguejo",
  "items:bait_crab:description": "Carne de caranguejo aberta e salgada para a viagem; as feras da cripta e da mata selvagem seguem o cheiro por milhas.",
  "items:bait_squid:name": "Isca de lula",
  "items:bait_squid:description": "Tiras de lula da costa profunda, escuras e oleosas; nada na praia nem nos poços de escória as ignora.",
  "items:bait_glow:name": "Isca luminosa",
  "items:bait_glow:description": "Vaga-lumes amarrados em uma isca de brilho fraco; as serpes das terras altas e os guardiões do salão do ídolo vêm até a luz.",
  "items:bait_worm:description": "Uma minhoca gorda e se contorcendo, escavada fresca na margem do rio, serve tanto para anzol quanto para armadilha.",

