  "actions:craft_godgem_reliquary:name": "Fabricar relicário de gema divina",
  "items:emberglass_loop:name": "Anel de Vidro de Brasa",
  "items:emberglass_loop:description": "Um fragmento de fogo engastado atrás de um vidro que o calor antigo tornou âmbar. Aquece a mão antes mesmo de qualquer feitiço ser lançado.",
  "items:hollowlight_seal:name": "Selo de Luz Oca",
  "items:hollowlight_seal:description": "Um fragmento de Aether selado em mithril, que brilha fracamente mesmo em plena luz do dia. O primeiro anel de que um mago não precisa se envergonhar.",
  "items:nightwell_loop:name": "Anel do Poço Noturno",
  "items:nightwell_loop:description": "Ônix enrolado em torno de um fragmento do vazio, tirando seu brilho de algo mais escuro que a luz da lua. Batizado em homenagem a um poço que nenhuma tocha jamais iluminou.",
  "items:voidscribe_glyph:name": "Bracelete do Escriba do Vazio",
  "items:voidscribe_glyph:description": "Uma pedra do vazio gravada com um glifo que se reescreve sozinho quando ninguém está olhando. Quem o usa aprende a não lê-lo com atenção demais.",
  "items:godsight_loop:name": "Anel da Visão Divina",
  "items:godsight_loop:description": "Uma gema divina engastada em prata abençoada, que dizem mostrar a quem a usa uma verdade antes de cada feitiço. Poucos afirmam gostar do que veem.",
  "items:ashcant_cord:name": "Pingente do Cântico de Cinzas",
  "items:ashcant_cord:description": "Um rubi enfiado em fio de ferro, envolto por um cântico entoado sobre cinzas. As palavras foram esquecidas há muito; o calor permanece.",
  "items:gravecall_sigil:name": "Amuleto do Chamado da Sepultura",
  "items:gravecall_sigil:description": "Uma pedra-de-sangue engastada em aço funerário e essência de túmulo, feita para invocar um escudo de um lugar que o conjurador não pode ver.",
  "items:duskveil_wreath:name": "Corrente do Véu Crepuscular",
  "items:duskveil_wreath:description": "Ônix envolto em runito e tecido fantasma, que dizem escurecer um pouco o ambiente onde quer que seja usado.",
  "items:voidsong_locket:name": "Amuleto do Canto do Vazio",
  "items:voidsong_locket:description": "Um relicário de pedra do vazio que entoa uma nota que mais ninguém consegue ouvir. Conjuradores juram que ele acompanha exatamente o ritmo de seu próprio pulso.",
  "items:godgem_reliquary:name": "Relicário de Gema Divina",
  "items:godgem_reliquary:description": "Um relicário de gema divina entrelaçado com tecido estelar, guardando o último escudo de uma conjuradora que nunca precisou de um segundo.",

  // ── Schmuck-Rework Welle 4 (29.08.2026): Nahkampf-Amulette + Fundstücke ─────────────────────
  "actions:craft_gorecrown_locket:name": "Forjar pingente da coroa sangrenta",
  "actions:craft_ironvow_collar:name": "Forjar corrente do juramento de ferro",
  "actions:craft_reavers_torc:name": "Fabricar torque do saqueador",
  "actions:craft_bloodiron_locket:name": "Fabricar medalhão de ferro-sangue",
  "actions:craft_warcrown_reliquary:name": "Fabricar relicário da coroa de guerra",
  "items:gorecrown_locket:name": "Pingente da Coroa Sangrenta",
  "items:gorecrown_locket:description": "Uma pedra-de-sangue engastada em aço funerário sobre couro de guerra, que dizem lembrar cada batalha da qual seu portador saiu vivo.",
  "items:ironvow_collar:name": "Corrente do Juramento de Ferro",
  "items:ironvow_collar:description": "Um diamante amarrado duas vezes em fio de mithril, usado por guerreiros que juraram um voto que pretendem sobreviver.",
  "items:reavers_torc:name": "Torque do Saqueador",
  "items:reavers_torc:description": "Ônix engastado duas vezes em runito, tomado de um saqueador que nunca deixou um inimigo escolher o terreno.",
  "items:bloodiron_locket:name": "Medalhão de Ferro-Sangue",
  "items:bloodiron_locket:description": "Um medalhão de pedra do vazio enrolado duas vezes em ferro-sangue. Não se abre para nada — a guerra que ele lembra terminou mal para todos os outros.",
  "items:warcrown_reliquary:name": "Relicário da Coroa de Guerra",
  "items:warcrown_reliquary:description": "Um relicário de gema divina engastado duas vezes em ferro divino, guardando a coroa de um senhor da guerra que nunca precisou erguê-la em sua defesa.",
  "items:cutthroat_loop:name": "Anel do Degolador",
  "items:cutthroat_loop:description": "Um anel de dentes de chacal, usado por caçadores que esperam uma ferida se abrir antes de atacar. Recompensa o golpe que encerra tudo.",
  "items:firstlight_seal:name": "Selo da Primeira Luz",
  "items:firstlight_seal:description": "Forjado da primeira brasa de um fogo de forja. Toda luta se decide no primeiro golpe, ou não se decide de jeito nenhum.",
  "items:tidewrack_collar:name": "Corrente dos Destroços da Maré",
  "items:tidewrack_collar:description": "Encrostada de sal e fria, tomada de uma cantora que afogava marinheiros com a própria voz. Transforma força roubada em escudo.",
  "items:hollowmarch_notch:name": "Faixa da Marcha Oca",
  "items:hollowmarch_notch:description": "Alisada por uma marcha sem fim através de salões ocos. Fica mais forte a cada passo que não para.",
  "items:ashenvow_locket:name": "Pingente do Voto de Cinzas",
  "items:ashenvow_locket:description": "Um voto jurado sobre brasas ardentes, mantido mesmo quando a chama se apagou. Golpeia mais forte com o último fôlego nos pulmões.",
  "items:rimeheart_locket:name": "Medalhão de Coração Gélido",
  "items:rimeheart_locket:description": "Congelado por completo por uma maga do gelo que nunca sentiu o frio. Pune tudo que já é lento demais para fugir.",
  "items:thornwarden_seal:name": "Selo do Guardião Espinhoso",
  "items:thornwarden_seal:description": "Esculpido por um guardião que transformava cada golpe recebido no próximo que desferia. Recompensa o lutador que ainda está de pé.",
  "items:sunder_crown:name": "Coroa Estilhaçada",
  "items:sunder_crown:description": "Estilhaçada de uma coroa que não governava reino algum, usada por quem domina todas as artes ao mesmo tempo. Um golpe fatal acerta mais forte quando poderia ter vindo de qualquer lugar.",

