  "items:nameless_longbow:name": "Arco dos Sem-Nome",
  "items:nameless_longbow:description": "Suas empunhaduras são tabuletas de nome em branco, sua corda um cordão de escriba desbotado. O que ele derruba não fica registrado.",
  "items:crownless_warbow:name": "Arco de Guerra do Sem-Coroa",
  "items:crownless_warbow:description": "Um arco pesado de ferro divino escuro, com pontas de coroa quebradas nos braços. Drazhan nunca precisou mirar em nada pequeno.",
  "items:hollowelm_staff:name": "Cajado de Olmo Oco",
