  "items:wreathbound_staff:name": "Cajado da Guirlanda",
  "items:emptied_shrine_focus:name": "Foco do Santuário Vazio",
  "items:expunger_chisel:name": "Cinzel do Expurgador",
  "items:expunger_chisel:description": "Um cinzel de ferro longo demais, com o cabo enrolado em cordão de escriba empoeirado. Foi feito para tirar coisas do mundo, e ainda o faz.",
  "items:crownless_stave:name": "Cajado do Sem-Coroa",
  "items:crownless_stave:description": "Um cajado de ferro divino negro da altura de um homem, com um engaste de coroa estourado e vazio no topo. Seu fogo foi emprestado uma vez e nunca devolvido.",
