  "items:duskfang_ripper:description": "Um punhal curvo forjado da garra de um abutre: leve, veloz e cruel ao desembainhar.",
  "items:ribcage_hewer:description": "Um machado de guerra de casca de ent, com o fio endurecido na seiva de Espinheiro Negro até morder como ferro.",
  "items:mossheart_crusher:description": "Uma maça de núcleo de golem feita de pedra e raízes compactadas. Cada golpe cai como uma muralha desabando.",
  "items:chorus_impaler:description": "Uma pique forjada na tumba, com a haste envolta em mortalha. O silêncio da cripta cavalga em sua ponta.",
  "items:sentinel_coreblade:description": "Uma espada de duas mãos forjada da placa-núcleo de um sentinela caído. Zumbe de leve com a carga de guarda que restou.",
  "items:colossus_marrowaxe:description": "Uma lâmina de machado colossal talhada em osso de tutano petrificado. Corta rumo ao maior alvo da sala.",
  "items:wisp_kindled_bough:description": "Um galho de madeira de pântano que ainda fumega com fogo-fátuo preso na ponta nodosa.",
  "items:chitinshell_sparker:description": "Uma varinha com núcleo de quitina de besouro, que faísca de estática a cada golpe.",
  "items:barrowsong_crook:description": "Um cetro funerário tomado de um cantor de túmulos, ainda frio ao toque.",
  "items:briarbound_conduit:description": "Um orbe catalisador preso em sarça viva, zumbindo com o ofício que sobrou da bruxa.",
  "items:choirbound_relic:description": "Um cajado resgatado do santuário do coro oco. Leva o zumbido deles a cada golpe.",
  "items:voidherald_flightbow:description": "Um arco longo encordoado com tendão tocado pelo vazio, tirado do relicário do próprio arauto.",
  "items:soulflayer_snapbow:description": "Um arco curto e cruel, talhado em chifre de almas esfoladas. Seu puxar é quase silencioso.",
  "items:voidhusk_deadeye:description": "Um pesado arco longo revestido de casca do vazio, feito para um único tiro mortal por vez.",
