  "quests:daily_ma_kill_gravecliff_specter_8:name": "Assombração no Penhasco",
  "quests:daily_ma_kill_gravecliff_specter_8:description": "Bana 8 espectros do Penhasco Tumular que assombram as pontes das Terras Altas.",
  "quests:daily_ma_kill_highland_wyvern_6:name": "Vigília das Wyverns",
  "quests:daily_ma_kill_highland_wyvern_6:description": "Abata 6 wyverns das terras altas antes que alcem voo.",
  "quests:daily_ma_kill_idol_warden_15:name": "Brecha dos Guardiões",
  "quests:daily_ma_kill_idol_warden_15:description": "Rompa a linha de 15 guardiões do ídolo que protegem o Santuário do Ídolo.",
  "quests:daily_ma_kill_aether_wraith_10:name": "Purga de Aether",
  "quests:daily_ma_kill_aether_wraith_10:description": "Desfaça 10 espectros de aether presos no Santuário do Ídolo.",
  "quests:daily_ma_kill_scale_skarn_8:name": "Caça ao Couro de Dragão",
  "quests:daily_ma_kill_scale_skarn_8:description": "Derrube 8 skarns de couro de dragão que fazem covil no Santuário do Ídolo.",
  "quests:daily_ma_smelt_godiron_3:name": "Crisol de Ferro Divino",
  "quests:daily_ma_smelt_godiron_3:description": "Funda 3 barras de ferro divino, o último degrau da escada de metais.",
  "quests:daily_ma_cook_witherleek_broth_20:name": "Cozinha do Caldo Arcano",
  "quests:daily_ma_cook_witherleek_broth_20:description": "Prepare 20 porções de caldo arcano de alho-poró murcho para a estrada.",
  "quests:daily_ma_gather_400:name": "Fartura do Segundo Volume",
  "quests:daily_ma_gather_400:description": "Colete 400 itens em um único dia, pois o reino ainda tem muito a dar.",
