  // claude:2026-10-18T00:30:00+02:00 — Talentbaum Jagdbuch (1.3.0 Säule 0).
  "talentTrees:slayer:name": "Livro do Caçador",
  "talentTrees:slayer:description": "O registro de caça de Brenna. Os Pontos de Caçador gastos aqui viram melhorias permanentes para toda a sua conta.",
  "talentBranches:slayer.companions:name": "Companheiros",
  "talentBranches:slayer.hunt:name": "A caçada",
  "talentBranches:slayer.lore:name": "Saber",
  "talentNodes:slayer.tracking:name": "Rastreamento",
  "talentNodes:slayer.tracking:description": "Cada companheiro cai {value} mais vezes.",
  "talentNodes:slayer.trail:name": "Na trilha",
  "talentNodes:slayer.trail:description": "Depois de {value} as tentativas esperadas sem companheiro, a próxima rolagem é garantida.",
  "talentNodes:slayer.collar:name": "Segunda coleira",
  "talentNodes:slayer.collar:description": "Libera um segundo espaço de companheiro. Lá só vale o efeito passivo.",
  "talentNodes:slayer.pace:name": "Ritmo de caça",
  "talentNodes:slayer.pace:description": "Tarefas concluídas rendem {value} mais Pontos de Caçador.",
  "talentNodes:slayer.spoils:name": "Espólios",
  "talentNodes:slayer.spoils:description": "Drops raros (1/500 ou mais raros) do monstro da sua tarefa ficam {value} mais prováveis.",
  "talentNodes:slayer.lore:name": "Saber do caçador",
  "talentNodes:slayer.lore:description": "Você causa {value} mais dano a famílias de monstros com o bestiário completo.",
  // claude:2026-10-18T12:00:00+02:00 — Narbenbuch (Prestige „Der Aschesturz“, Welle B2): Baum, Äste, Knoten.
  "talentTrees:prestige:name": "Livro das Cicatrizes",
  "talentTrees:prestige:description": "O registro do Guardião sobre cada Queda das Cinzas. As cicatrizes conquistadas no Altar dos Fragmentos se tornam aqui dádivas duradouras para cada partida seguinte.",
  "talentBranches:prestige.legacy:name": "O que resta",
  "talentBranches:prestige.haste:name": "O caminho curto",
  "talentBranches:prestige.might:name": "Marcado",
  "talentBranches:prestige.crown:name": "Pedra-chave",
  "talentNodes:prestige.startingGold:name": "Moedas de túmulo",
  "talentNodes:prestige.startingGold:description": "Você começa cada nova partida com {value} de ouro. Os mortos recebem moedas para a viagem. Você não está morto, mas as moedas não atrapalham.",
  "talentNodes:prestige.keepTools:name": "Calos",
  "talentNodes:prestige.keepTools:description": "Todas as suas ferramentas sobrevivem à Queda das Cinzas e esperam por você no banco. As mãos não esquecem suas ferramentas.",
  "talentNodes:prestige.keepBankStacks:name": "Baú enterrado",
  "talentNodes:prestige.keepBankStacks:description": "{value} pilhas de materiais ou consumíveis sobrevivem à Queda das Cinzas, até 50 de cada. O que estava enterrado nunca viu o fogo.",
  "talentNodes:prestige.keepEquipment:name": "Herança",
  "talentNodes:prestige.keepEquipment:description": "O equipamento escolhido sobrevive à Queda das Cinzas (peças: {value}) se cada peça exigir nível 80 ou mais. Uma peça que as cinzas não levam.",
  "talentNodes:prestige.earlyXp:name": "Anos de aprendiz",
  "talentNodes:prestige.earlyXp:description": "{value} mais experiência de habilidade abaixo do nível 80. O que se aprendeu uma vez se aprende mais rápido na segunda.",
  "talentNodes:prestige.chronicleRecall:name": "Páginas conhecidas",
  "talentNodes:prestige.chronicleRecall:description": "Os capítulos 1 a 18 da Crônica que você já viveu podem ser concluídos com um clique, pela metade do ouro e sem fichas nem itens. A Crônica não lê para você duas vezes um capítulo que você já viveu.",
  "talentNodes:prestige.masteredXp:name": "Segunda natureza",
  "talentNodes:prestige.masteredXp:description": "{value} mais experiência até o nível 99 nas habilidades que você já dominou uma vez. Suas mãos ainda sabem aonde ir.",
  "talentNodes:prestige.dungeonRecall:name": "Velhos caminhos",
  "talentNodes:prestige.dungeonRecall:description": "As masmorras que você limpou em uma partida anterior ficam abertas para você de imediato. Os portões que você limpou uma vez reconhecem você.",
  "talentNodes:prestige.maxHp:name": "Tecido cicatricial",
  "talentNodes:prestige.maxHp:description": "{value} mais vida máxima. Tecido cicatricial não se rasga tão fácil.",
  "talentNodes:prestige.damage:name": "Punho cicatrizado",
  "talentNodes:prestige.damage:description": "Você causa {value} mais dano. Os nós dos dedos que já quebraram uma vez não quebram de novo.",
  "talentNodes:prestige.goldFind:name": "Olho de pega",
  "talentNodes:prestige.goldFind:description": "{value} mais ouro de ações, combates, masmorras e missões, mas não de vendas. Você recolhe o que pertencia aos ídolos, como as pegas recolhem prata.",
  "talentNodes:prestige.pointsBoost:name": "O corte mais fundo",
  "talentNodes:prestige.pointsBoost:description": "Cada futura Queda das Cinzas concede {value} mais cicatrizes. A próxima queda corta mais fundo e deixa mais para trás.",
